facts=[dict(id='F-commit-accounting',meaning='For each retained voter ID, the leader-term commitment object records the greatest matched index reported by local storage or that peer replication path.',identity={'leader':'commitment object instance','peer':'ServerID'},validity_context='One leadership instance and its currently installed voter set; meaning depends on producer response correctness.',representation=['commitment.matchIndexes'],durability='Volatile aggregation; successful producers refer to stored log or installed snapshot.',recovery='Rebuilt empty on every leader entry; established persistent history is rediscovered by replication.',source_ids=['S-commit','S-append','S-replicate','S-send-snapshot'],reinterpreters=['B-membership'],invalidators=['B-leader-lifetime']),dict(id='F-verify-tally',meaning='A verifyFuture carries an integer tally initialized with self support and incremented by positive notifications from registered replication peers; reaching quorum queues it for leader-loop consumption. The tally does not itself encode voter identity or suffrage.',identity={'operation':'verifyFuture object'},validity_context='Pending verification in one leader instance; notifyCh becomes nil after a decisive notification. Configuration changes during an operation are not yet analyzed.',representation=['verifyFuture.votes','verifyFuture.quorumSize','verifyFuture.notifyCh'],durability='Volatile, per-invocation.',recovery='Not recovered; retained pending futures are failed on leader exit.',source_ids=['S-verify','S-verify-vote','S-loop','S-replicate'],invalidators=['B-leader-lifetime'])]
